package ru.neverland.archaeology.restoration;
import java.util.*;import java.util.concurrent.*;import org.bukkit.plugin.Plugin;import ru.neverland.core.*;
import static ru.neverland.archaeology.restoration.RestorationBook.*;
/** The durable book is authoritative. Audit repair never gives or consumes an item. */
final class RestorationAudit {
    private final Plugin plugin;private final ThreadPoolExecutor worker;private final CompletableFuture<Void> closed=new CompletableFuture<>();private final Set<String> recorded=new HashSet<>();private State snapshot;private Iterator<Source> sources;private Iterator<Operation> operations;private long completedRevision=-1;private volatile boolean busy,closing;private long retryAt;
    RestorationAudit(Plugin plugin){this.plugin=plugin;worker=new ThreadPoolExecutor(1,1,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<>(1),r->{var t=new Thread(r,"NeverLand-restoration-audit");t.setDaemon(true);return t;},new ThreadPoolExecutor.AbortPolicy()){@Override protected void terminated(){closed.complete(null);}};}
    void pulse(State current){if(closing||busy||System.currentTimeMillis()<retryAt)return;if(snapshot==null){if(completedRevision==current.revision())return;snapshot=current;sources=current.sources().values().iterator();operations=current.operations().values().iterator();}var batch=new ArrayList<AuditRecord>();int visited=0;while(sources.hasNext()&&visited++<128){var source=sources.next();if(source.fragment()!=null){var f=snapshot.fragments().get(source.fragment());batch.add(source(source,f));}}while(!sources.hasNext()&&operations.hasNext()&&visited++<128)batch.add(operation(operations.next()));boolean finished=!sources.hasNext()&&!operations.hasNext();long revision=snapshot.revision();busy=true;try{worker.execute(()->{boolean success=true;try{for(var record:batch)if(!recorded.contains(record.id())){if(AuditTrail.record(plugin,record))recorded.add(record.id());else success=false;}}finally{try(var guard=SuiteState.guard()){if(!success){snapshot=null;retryAt=System.currentTimeMillis()+30000;}else if(finished){completedRevision=revision;snapshot=null;}busy=false;}}});}catch(RejectedExecutionException full){busy=false;snapshot=null;retryAt=System.currentTimeMillis()+30000;}}
    private AuditRecord source(Source source,Fragment f){String operation=source.id().toString();var actor=player(source.player(),source.playerName());return new AuditRecord(AuditRecord.id(plugin.getName(),operation,"fragment-entitlement"),source.at(),plugin.getName(),"ARCHAEOLOGY_FRAGMENT","MAILBOX",operation,actor,AuditRecord.Party.unknown(),actor,f.recipe().artifact(),1,"0","Источник="+source.origin()+"; fragment="+f.id()+"; part="+f.part()+"/"+f.recipe().parts()+"; rarity="+f.recipe().rarity()+"; получено право на выдачу, инвентарь ещё не подтверждён");}
    private AuditRecord operation(Operation op){String id=op.id().toString();var actor=player(op.player(),op.playerName());return new AuditRecord(AuditRecord.id(plugin.getName(),id,"restoration-"+op.phase()),op.at(),plugin.getName(),op.kind()==Kind.CLAIM?"ARCHAEOLOGY_FRAGMENT":"ARCHAEOLOGY_RESTORATION",op.phase().name(),id,actor,actor,actor,op.recipe().artifact(),op.kind()==Kind.CLAIM?1:op.fragments().size(),"0","kind="+op.kind()+"; inputs="+op.fragments()+"; output="+op.output()+"; frozenParts="+op.recipe().parts()+"; rarity="+op.recipe().rarity()+"; время начала операции; "+op.note());}
    private static AuditRecord.Party player(UUID id,String name){return new AuditRecord.Party("PLAYER",id.toString(),name,"");}
    CompletionStage<Void> closeAsync(){closing=true;worker.shutdown();return closed;}
}
